-- m64 (Lote B): catálogos das lojas variando de cidade para cidade (só itens com efeito real) + Vara de Pesca nos portos.
do $$ begin
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "potion", "preco": 300}, {"item": "antidote", "preco": 100}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'pallet';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "potion", "preco": 300}, {"item": "antidote", "preco": 100}, {"item": "awakening", "preco": 250}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'verdelume';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'estufa1' then jsonb_set(q, '{estoque}', '[{"item": "potion", "preco": 300}, {"item": "antidote", "preco": 100}, {"item": "awakening", "preco": 250}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'verdelume';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "great-ball", "preco": 600}, {"item": "potion", "preco": 300}, {"item": "super-potion", "preco": 700}, {"item": "antidote", "preco": 100}, {"item": "paralyze-heal", "preco": 200}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'ambar';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'olaria' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "potion", "preco": 300}, {"item": "antidote", "preco": 100}, {"item": "burn-heal", "preco": 250}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'argila';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "great-ball", "preco": 600}, {"item": "potion", "preco": 300}, {"item": "super-potion", "preco": 700}, {"item": "burn-heal", "preco": 250}, {"item": "awakening", "preco": 250}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'argila';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "great-ball", "preco": 600}, {"item": "super-potion", "preco": 700}, {"item": "revive", "preco": 1500}, {"item": "ice-heal", "preco": 250}, {"item": "full-heal", "preco": 600}, {"item": "poke-ball", "preco": 200}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'quartzo';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "great-ball", "preco": 600}, {"item": "ultra-ball", "preco": 1200}, {"item": "super-potion", "preco": 700}, {"item": "hyper-potion", "preco": 1200}, {"item": "paralyze-heal", "preco": 200}, {"item": "full-heal", "preco": 600}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'ametista';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "great-ball", "preco": 600}, {"item": "ultra-ball", "preco": 1200}, {"item": "hyper-potion", "preco": 1200}, {"item": "revive", "preco": 1500}, {"item": "burn-heal", "preco": 250}, {"item": "full-heal", "preco": 600}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'carmesim';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "ultra-ball", "preco": 1200}, {"item": "hyper-potion", "preco": 1200}, {"item": "max-potion", "preco": 2500}, {"item": "revive", "preco": 1500}, {"item": "max-revive", "preco": 4000}, {"item": "full-heal", "preco": 600}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'obsidiana';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'mart' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "great-ball", "preco": 600}, {"item": "potion", "preco": 300}, {"item": "super-potion", "preco": 700}, {"item": "antidote", "preco": 100}, {"item": "old-rod", "preco": 800}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'azurana';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'loja' then jsonb_set(q, '{estoque}', '[{"item": "poke-ball", "preco": 200}, {"item": "great-ball", "preco": 600}, {"item": "potion", "preco": 300}, {"item": "super-potion", "preco": 700}, {"item": "antidote", "preco": 100}, {"item": "old-rod", "preco": 800}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'porto';
  update public.mapas set pois = (select jsonb_agg(case when q->>'id' = 'feira' then jsonb_set(q, '{estoque}', '[{"item": "potion", "preco": 300}, {"item": "poke-ball", "preco": 200}, {"item": "awakening", "preco": 250}, {"item": "old-rod", "preco": 800}]'::jsonb) else q end order by o) from jsonb_array_elements(pois) with ordinality t(q, o)) where id = 'porto';
end $$;
